values.content:
=Please recommend 5 gift ideas for:
- Age: {{ $json.age }}
- Gender: {{ $json.gender }}
- Interests: {{ $json.interests }}
- Budget: {{ $json.budget }}
- Occasion: {{ $json.occasion }}
- Relationship: {{ $json.relationship }}

Provide specific product suggestions that I can search for online.

parameters.jsCode:
// Parse AI response and extract gift suggestions
const aiResponse = $input.first().json.message.content;

let giftIdeas;
try {
  // Try to parse as JSON first
  const jsonMatch = aiResponse.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (jsonMatch) {
    giftIdeas = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback parsing if AI doesn't return pure JSON
    giftIdeas = JSON.parse(aiResponse);
  }
} catch (error) {
  // If parsing fails, create a simple structure
  console.log('Failed to parse AI response, using fallback');
  giftIdeas = [
    {
      giftName: "Gift Idea 1",
      description: "Please check AI response",
      estimatedPrice: "N/A",
      searchKeywords: $input.first().json.interests || "gift",
      category: "General"
    }
  ];
}

// Return each gift idea as a separate item for processing
return giftIdeas.map((gift, index) => ({
  json: {
    giftIndex: index + 1,
    giftName: gift.giftName,
    description: gift.description,
    estimatedPrice: gift.estimatedPrice,
    searchKeywords: gift.searchKeywords,
    category: gift.category,
    userPreferences: {
      age: $input.first().json.age,
      budget: $input.first().json.budget,
      occasion: $input.first().json.occasion
    }
  }
}));

// Process and rank product search results
const items = $input.all();
const processedGifts = [];

for (const item of items) {
  const data = item.json;

  let products = [];

  // Check if we have SerpAPI results
  if (data.shopping_results && Array.isArray(data.shopping_results)) {
    products = data.shopping_results.slice(0, 3).map(product => ({
      productName: product.title,
      price: product.price || product.extracted_price || 'Price not available',
      link: product.link,
      source: product.source || 'Online Store',
      rating: product.rating || 'N/A',
      thumbnail: product.thumbnail
    }));
  }

  // Create gift suggestion object
  const giftSuggestion = {
    giftIndex: data.giftIndex || processedGifts.length + 1,
    giftName: data.giftName,
    description: data.description,
    category: data.category,
    estimatedPrice: data.estimatedPrice,
    products: products,
    bestDeal: products.length > 0 ? products[0] : null,
    searchKeywords: data.searchKeywords
  };

  processedGifts.push({ json: giftSuggestion });
}

// Sort by best deals (if available) and limit to top 5
processedGifts.sort((a, b) => {
  // Prioritize items with products found
  if (a.json.products.length > 0 && b.json.products.length === 0) return -1;
  if (a.json.products.length === 0 && b.json.products.length > 0) return 1;
  return 0;
});

return processedGifts.slice(0, 5);

// Format final response
const gifts = $input.all();

const response = {
  success: true,
  requestedAt: new Date().toISOString(),
  totalSuggestions: gifts.length,
  userPreferences: gifts[0]?.json?.userPreferences || {},
  suggestions: gifts.map(item => item.json)
};

return [{ json: response }];
